style.css:
@-moz-document domain("youtube.com") {
:root {
        /* Core variables integrated directly from your style rules */
        --sailor-main-bg: url("https://i.pinimg.com/736x/19/cb/ee/19cbeeaf6ab2242a8bddd16164aaa2c6.jpg");
        --sailor-overlay: rgba(255, 238, 240, 0.85);
        
        /* Your Palette Definitions */
        --sailor-pink: #ce67b6;       
        --sailor-yellow: #fff1cf;     
        --sailor-purple: #cda3f6;     
        --sailor-dark-text: #808080;  
    }

    /* Gradient backdrop styling from your General rules block */
    html, body, ytd-app {
        background: var(--sailor-main-bg), linear-gradient(-2deg, #fdd6e9 25%, #f2d1fe 80%) !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        text-align: justify !important;
    }

    /* ==========================================================================
       2. TYPOGRAPHY LAYER (Sofia & ABeeZee)
       ========================================================================== */
    /* System elements styled with ABeeZee & Sofia combinations */
    body, yt-formatted-string, span, a, input, button, 
    .yt-core-attributed-string, #content-text {
        font-family: 'ABeeZee', sans-serif !important;
        font-style: italic !important;
        text-shadow: 0px 0px 2px #FFFFFF !important;
    }

    /* Header titles fallback to Sofia layout rule */
    h1, h2, h3, #video-title, .title.ytd-video-primary-info-renderer {
        font-family: 'Sofia', cursive !important;
        font-style: italic !important;
        font-weight: normal !important;
        color: #ce67b6 !important;
        text-shadow: 0px 0px 2px #FFFFFF !important;
    }

    /* ==========================================================================
       3. TRANSPARENCY LAYERS
       ========================================================================== */
    ytd-page-manager, 
    #contentContainer.ytd-app, 
    #columns.ytd-watch-flexy, 
    ytd-browse, 
    ytd-guide-renderer,
    #masthead-container.ytd-app,
    ytd-masthead {
        background: transparent !important;
    }

    /* Elegant frosted pink overlay containers */
    ytd-rich-grid-renderer, 
    #secondary.ytd-watch-flexy, 
    #watch7-sidebar,
    ytd-playlist-panel-renderer {
        background-color: var(--sailor-overlay) !important;
        border: #FFFFFF 1px dotted !important;
        border-radius: 10px !important;
        padding: 15px !important;
        backdrop-filter: blur(5px) !important; 
        text-shadow: 0px 0px 2px #FFFFFF !important;
    }

    /* Main Navigation Header line matching your Cabecera style */
    #background.ytd-masthead {
        background: url("https://giphy.com"),
                    linear-gradient(to right, #fcdde4ad, #eedaf9ad) !important;
        border-bottom: 1px solid #ffeef04a !important;
        box-shadow: 0px 4px 0px 1px #fffff85 !important;
        backdrop-filter: blur(5px) !important;
    }

    /* ==========================================================================
       4. SYSTEM ATTRIBUTE RE-MAPPING
       ========================================================================== */
    html, [theme="light"] {
        --yt-spec-base-background: transparent !important;
        --yt-spec-text-primary: var(--sailor-dark-text) !important;
        --yt-spec-text-secondary: var(--sailor-pink) !important;
        --yt-spec-brand-red: var(--sailor-pink) !important;
        --yt-spec-static-brand-red: var(--sailor-pink) !important;
        --yt-spec-call-to-action: var(--sailor-pink) !important;
        --yt-spec-static-brand-background-solid: var(--sailor-pink) !important;
    }

    /* Soft thumbnail curves */
    ytd-thumbnail img, ytd-thumbnail {
        border-radius: 10px !important;
    }

    /* Custom Search box wrapper matching code elements */
    #container.ytd-searchbox {
        background: linear-gradient(to right, #ffede2, #fff5db) !important;
        border: 1px solid #FFFFFF !important;
        border-radius: 10px 0 0 10px !important;
    }
    
    #search-icon-legacy.ytd-searchbox {
        background: linear-gradient(-2deg, #fae3f7 25%, #f2d1fe 80%) !important;
        border: 1px solid #FFFFFF !important;
        border-radius: 0 10px 10px 0 !important;
    }

    /* =webkit-scrollbar properties tracking template curves */
    ::-webkit-scrollbar {
        width: 10px !important;
    }
    ::-webkit-scrollbar-track {
        background: #ffebee !important;
    }
    ::-webkit-scrollbar-thumb {
        background: #f2d1fe !important;
        border: 1px solid #FFFFFF !important;
        border-radius: 5px !important;
    }
}
